window.QBANK['m5w4'] = [
  {"level": 1, "q": "Vì sao agent production cần hằng số như MAX_TURNS = 15?", "options": ["Để model trả lời nhanh hơn mỗi lượt", "Vì API chỉ cho phép tối đa 15 message", "Để tăng tỉ lệ cache hit", "Để agent dừng khi lặp quá nhiều, tránh vòng lặp vô hạn và chi phí không kiểm soát"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Giới hạn số vòng là lớp an toàn đầu tiên: agent có thể mắc kẹt khi tool trả kết quả mơ hồ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giới hạn vòng không đổi tốc độ mỗi lượt; API không giới hạn 15 message; không liên quan cache."},
  {"level": 1, "q": "stop_reason bằng \"refusal\" nghĩa là gì?", "options": ["Claude từ chối yêu cầu vì lý do an toàn; nên dừng và chuyển người xem xét", "Tool trả lỗi", "Output bị cắt vì hết max_tokens", "Claude đã hoàn thành"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> refusal báo model từ chối; response có thể kèm stop_details mô tả phân loại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lỗi tool thể hiện qua tool_result is_error; bị cắt là max_tokens; hoàn thành là end_turn."},
  {"level": 1, "q": "stop_reason bằng \"max_tokens\" cho biết điều gì?", "options": ["Đã dùng hết ngân sách token của tháng", "Context window đã đầy", "Output bị cắt vì chạm giới hạn max_tokens của request", "Model muốn gọi tool"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> max_tokens là trần cứng cho một response; nội dung có thể dở dang (JSON thiếu ngoặc, code thiếu đoạn).<br><strong>Vì sao các lựa chọn khác sai:</strong> Không liên quan hạn mức tháng; context đầy là lỗi khác; gọi tool là tool_use."},
  {"level": 1, "q": "stop_reason \"pause_turn\" thường xuất hiện khi nào?", "options": ["Khi người dùng bấm dừng", "Khi API key hết hạn", "Trong luồng agentic có server tool chạy lâu, model tạm dừng và có thể tiếp tục bằng cách gửi lại lượt assistant", "Khi rate limit 429"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> pause_turn nghĩa là lượt bị tạm dừng và có thể resume; không xử lý thì câu trả lời bị cụt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Người dùng dừng không sinh stop_reason này; key hết hạn và 429 là lỗi HTTP."},
  {"level": 1, "q": "Trường is_error: true trong tool_result dùng để làm gì?", "options": ["Dừng toàn bộ request API", "Báo cho Claude biết tool thất bại, kèm thông điệp hướng dẫn nên làm gì tiếp", "Báo lỗi cho AWS CloudWatch", "Yêu cầu Anthropic hoàn tiền token"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Claude đọc nội dung lỗi để điều chỉnh (thử cách khác, báo người dùng) thay vì hiểu nhầm là kết quả hợp lệ.<br><strong>Vì sao các lựa chọn khác sai:</strong> is_error không dừng request; không tự gửi log lên CloudWatch; không liên quan hoàn tiền."},
  {"level": 1, "q": "Theo bài học, retry cho lỗi tạm thời (timeout, 503) nên đặt ở đâu?", "options": ["Để model tự gọi lại tool nhiều lần", "Ở phía người dùng bấm lại", "Không retry bao giờ", "Ở tầng tool, có backoff, trước khi trả kết quả cho model"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Retry ở tầng tool rẻ hơn và chắc chắn hơn; model tự retry tốn lượt và token.<br><strong>Vì sao các lựa chọn khác sai:</strong> Để model retry dẫn tới vòng lặp như ví dụ 37 lần; bắt người dùng bấm lại kém trải nghiệm; không retry thì lỗi thoáng qua thành thất bại."},
  {"level": 1, "q": "Lỗi nào KHÔNG nên retry?", "options": ["Timeout mạng", "Lỗi dữ liệu đầu vào, ví dụ mã sản phẩm không tồn tại", "HTTP 503 Service Unavailable", "HTTP 429 do rate limit"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lỗi vĩnh viễn sẽ lặp lại dù thử bao nhiêu lần; nên trả is_error kèm hướng dẫn định dạng đúng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Timeout, 503 và 429 là lỗi tạm thời, retry có backoff thường thành công."},
  {"level": 1, "q": "Hành động nào nên yêu cầu con người phê duyệt trước khi agent thực hiện?", "options": ["Đọc file README", "Tìm kiếm trong tài liệu nội bộ", "Tính tổng một mảng số", "Hành động không đảo ngược được hoặc rủi ro cao, như hoàn tiền lớn, xoá dữ liệu, gửi email cho khách"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Human-in-the-loop dành cho thao tác có hậu quả thật và khó hoàn tác.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đọc, tìm kiếm, tính toán là thao tác an toàn, không cần duyệt."},
  {"level": 1, "q": "Log từng bước của agent nên ghi những gì?", "options": ["Chỉ câu trả lời cuối", "Toàn bộ API key để debug", "Số lượt, tool gọi, input, output rút gọn, token và stop_reason", "Chỉ thời điểm bắt đầu"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Log đủ chi tiết giúp truy lại mọi quyết định của agent và debug khi có sự cố.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ câu cuối không giải thích được vì sao; không bao giờ log secret; mỗi thời điểm bắt đầu là quá ít."},
  {"level": 1, "q": "Eval agent nên chấm chủ yếu dựa trên gì?", "options": ["Agent có đi đúng kịch bản mẫu từng bước không", "Kết quả cuối cùng (test pass, label đúng), không phải từng bước đi", "Số dòng code agent viết", "Độ dài câu trả lời"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Agent có thể đi đường khác nhưng vẫn đúng; chấm kết quả cuối không phạt cách làm hợp lệ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chấm từng bước phạt cách làm đúng khác kịch bản; số dòng code và độ dài không phản ánh chất lượng."},
  {"level": 1, "q": "Vì sao nên chạy mỗi test case của eval nhiều lần?", "options": ["Kết quả model có tính ngẫu nhiên; cần tỉ lệ thành công thay vì một lần đúng/sai", "Để tăng hoá đơn API", "Vì API trả lỗi lần đầu", "Để làm nóng cache bắt buộc"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Chạy nhiều lần cho ước lượng ổn định hơn và lộ ra case chập chờn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Mục tiêu không phải tăng chi phí; API không lỗi lần đầu theo quy luật; cache không bắt buộc làm nóng."},
  {"level": 1, "q": "Tách tập dev và tập test trong eval để làm gì?", "options": ["Để chạy nhanh gấp đôi", "Vì API yêu cầu hai tập", "Tinh chỉnh prompt trên tập dev, báo cáo trên tập test để tránh ảo tưởng do khớp quá mức", "Để dùng hai model khác nhau"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nếu tinh chỉnh và báo cáo trên cùng tập, điểm số bị thổi phồng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tách tập không nhằm tăng tốc; API không yêu cầu; không liên quan chọn model."},
  {"level": 1, "q": "Thứ tự tối ưu chi phí được bài học khuyến nghị là gì?", "options": ["Đổi ngay sang model rẻ nhất", "Giảm max_tokens xuống thấp nhất", "Tắt bớt tool", "Tối ưu miễn phí trước (caching, cắt token, Batch, giảm vòng thừa), rồi mới đánh đổi (giảm effort, đổi model, routing)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Đòn bẩy miễn phí không giảm chất lượng; đánh đổi chỉ làm khi có eval.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model ngay có thể giảm chất lượng và mất cache; max_tokens quá thấp gây cắt output; tắt tool làm hỏng chức năng."},
  {"level": 1, "q": "Batch API giảm chi phí khoảng bao nhiêu so với request thường?", "options": ["Khoảng 50%", "Khoảng 10%", "Khoảng 90%", "Không giảm, chỉ nhanh hơn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Message Batches xử lý bất đồng bộ với giá bằng một nửa, hợp việc không cần realtime.<br><strong>Vì sao các lựa chọn khác sai:</strong> 10% và 90% không đúng mức giảm của Batch; Batch không nhanh hơn mà chậm hơn."},
  {"level": 1, "q": "Batch API thường hoàn thành trong bao lâu?", "options": ["Luôn dưới 1 giây", "Đúng 7 ngày", "Chỉ chạy vào ban đêm", "Phần lớn trong vòng 1 giờ, tối đa 24 giờ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Batch là bất đồng bộ: đa số xong trong một giờ nhưng có thể tới 24 giờ, nên chỉ dùng khi chấp nhận chờ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không phải realtime; không có thời hạn cố định 7 ngày; không giới hạn theo giờ trong ngày."},
  {"level": 1, "q": "Token đọc từ cache (cache_read_input_tokens) có giá xấp xỉ bao nhiêu so với token input thường?", "options": ["Khoảng 1,25 lần", "Khoảng 0,1 lần", "Miễn phí hoàn toàn", "Khoảng 2 lần"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đọc cache rất rẻ nên phần prefix lớn, ổn định (system prompt, tài liệu, schema) nên được cache.<br><strong>Vì sao các lựa chọn khác sai:</strong> 1,25 lần là giá ghi cache TTL 5 phút; không miễn phí; 2 lần không phải giá đọc cache."},
  {"level": 1, "q": "Ghi cache với TTL mặc định 5 phút tốn khoảng bao nhiêu so với input thường?", "options": ["Khoảng 0,1 lần", "Khoảng 1,25 lần", "Khoảng 0,5 lần", "Bằng đúng giá input"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lần đầu ghi cache đắt hơn một chút, các lần đọc sau rẻ hơn nhiều nên có lợi khi prefix được dùng lại.<br><strong>Vì sao các lựa chọn khác sai:</strong> 0,1 lần là giá đọc; 0,5 lần là mức giảm của Batch; không bằng giá input."},
  {"level": 1, "q": "Task budget (beta) khác max_tokens thế nào?", "options": ["Task budget là ngân sách token model được biết để tự điều tiết cả nhiệm vụ; max_tokens là trần cứng cho một response mà model không biết", "Hai khái niệm giống nhau", "max_tokens áp dụng cho cả vòng lặp", "Task budget tính bằng USD"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Model biết task budget nên có thể phân bổ công sức; max_tokens chỉ cắt output khi chạm trần.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hai cơ chế khác nhau; max_tokens áp dụng từng response; task budget tính bằng token."},
  {"level": 1, "q": "Vì sao nên đo \"chi phí trên mỗi nhiệm vụ hoàn thành\" thay vì \"chi phí mỗi request\"?", "options": ["Vì Anthropic tính tiền theo nhiệm vụ", "Vì request không có giá", "Request rẻ nhưng hay thất bại phải chạy lại thì tổng chi phí để có một kết quả đúng có thể cao hơn", "Vì dễ tính hơn"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chỉ số đúng phản ánh cả tỉ lệ thành công, số lần chạy lại và chi phí xử lý thất bại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Anthropic tính theo token; mỗi request đều có giá; lý do không phải là dễ tính."},
  {"level": 1, "q": "Các mức effort hợp lệ trong output_config là gì?", "options": ["fast, normal, slow", "1 đến 10", "low, medium, high, xhigh, max", "mini, standard, pro"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> effort điều chỉnh mức suy nghĩ/token model dùng; giảm effort là một đòn bẩy đánh đổi sau khi có eval.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các tập giá trị khác không phải tham số của API."},
  {"level": 1, "q": "Vì sao chiến lược \"nhiều model\" (routing) có thể làm mất lợi ích caching?", "options": ["Cache gắn với model; chuyển request sang model khác thì prefix phải ghi cache lại", "Vì model rẻ không hỗ trợ caching", "Vì routing tắt caching toàn tài khoản", "Vì cache chỉ tồn tại 1 giây"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Bài học lưu ý nên đo phương án một model với effort thấp hơn trước khi chia nhiều model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Model rẻ vẫn hỗ trợ caching; routing không tắt caching toàn cục; TTL mặc định là 5 phút."},
  {"level": 1, "q": "\"Checkpoint để rollback\" trong độ tin cậy agent nghĩa là gì?", "options": ["Lưu API key dự phòng", "Lưu trạng thái trước thay đổi (ví dụ commit git, snapshot DB) để hoàn tác khi agent làm sai", "Đặt breakpoint trong IDE", "Tăng max_turns"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Có điểm khôi phục giúp giảm thiệt hại khi agent thay đổi sai.<br><strong>Vì sao các lựa chọn khác sai:</strong> API key dự phòng, breakpoint và số lượt không phải cơ chế hoàn tác."},
  {"level": 1, "q": "\"Kiểm chứng\" trong độ tin cậy agent là gì?", "options": ["Cho agent cách tự kiểm tra kết quả (chạy test, validate schema) trước khi báo xong", "Hỏi agent \"bạn chắc chưa?\"", "Tăng temperature", "Đọc lại prompt"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tín hiệu kiểm chứng khách quan giúp agent phát hiện và tự sửa lỗi trước khi kết thúc.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hỏi lại không phải kiểm chứng khách quan; temperature và đọc lại prompt không kiểm tra kết quả."},
  {"level": 1, "q": "Ngoài tỉ lệ thành công, eval agent nên theo dõi thêm chỉ số nào?", "options": ["Số emoji trong câu trả lời", "Màu giao diện", "Số lượt, token, thời gian chạy và tỉ lệ cần con người can thiệp", "Số commit trong ngày"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Các chỉ số vận hành cho thấy chi phí và độ trễ, giúp so sánh cấu hình đầy đủ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các lựa chọn khác không phản ánh chất lượng hay chi phí agent."},
  {"level": 1, "q": "Trong vòng lặp có kiểm soát, stop_reason \"end_turn\" nên được xử lý thế nào?", "options": ["Gửi thêm tool_result rỗng", "Kiểm chứng kết quả rồi kết thúc vòng lặp", "Tăng max_tokens và gọi lại", "Coi là lỗi"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> end_turn nghĩa là Claude hoàn tất lượt; flow bài học: kiểm chứng rồi kết thúc.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có tool_use cần trả lời; không cần gọi lại; end_turn là trạng thái bình thường."},
  {"level": 1, "q": "Người dùng từ chối một tool nguy hiểm. Vòng lặp nên làm gì với khối tool_use đó?", "options": ["Bỏ qua, không gửi gì", "Xoá khối tool_use khỏi lịch sử", "Kết thúc chương trình", "Vẫn gửi tool_result cho đúng tool_use_id với is_error và nội dung \"người dùng từ chối\""], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mỗi tool_use phải có tool_result; thông báo từ chối giúp Claude đề xuất phương án khác.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thiếu tool_result gây lỗi API; sửa lịch sử làm hỏng tính nhất quán; kết thúc chương trình là quá mức."},
  {"level": 1, "q": "Backoff tăng dần với base 1 giây, thử 3 lần sẽ chờ lần lượt bao lâu?<pre><code>const delay = (i: number, base = 1000) =&gt; base * 2 ** i;\n[0, 1, 2].map((i) =&gt; delay(i)); // ?</code></pre>", "options": ["1 giây, 1 giây, 1 giây", "3 giây, 3 giây, 3 giây", "0 giây, 10 giây, 100 giây", "1 giây, 2 giây, 4 giây"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Exponential backoff: base × 2^i, giảm áp lực lên hệ thống đang lỗi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chờ cố định không phải backoff tăng dần; dãy nhân 10 không khớp công thức."},
  {"level": 1, "q": "Kết quả Batch API được lưu để tải về trong bao lâu sau khi tạo batch?", "options": ["29 ngày", "1 giờ", "24 giờ", "Vĩnh viễn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Kết quả có sẵn trong 29 ngày, nên job thu kết quả cần chạy trong khoảng này.<br><strong>Vì sao các lựa chọn khác sai:</strong> 1 giờ và 24 giờ là mốc thời gian xử lý; kết quả không lưu vĩnh viễn."},
  {"level": 1, "q": "\"Routing nhiều model\" nghĩa là gì?", "options": ["Gửi cùng request tới mọi model rồi lấy kết quả nhanh nhất", "Đổi vùng AWS theo giờ", "Dùng nhiều API key", "Gửi việc dễ cho model rẻ/nhanh, việc khó cho model mạnh, dựa trên tiêu chí phân loại"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Routing là đánh đổi nằm ở nhóm sau cùng, chỉ làm khi eval cho thấy lợi ích.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gửi mọi model là tốn gấp nhiều lần; vùng AWS và API key không phải routing model."},
  {"level": 1, "q": "Câu nào là \"bẫy đề thi\" hay gặp về tối ưu chi phí?", "options": ["\"Bật prompt caching cho system prompt dài\"", "\"Dùng Batch API cho việc chạy qua đêm\"", "\"Đổi ngay sang model rẻ nhất\" khi chưa có eval", "\"Đo chi phí trên mỗi nhiệm vụ hoàn thành\""], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Không có eval thì không biết chất lượng giảm bao nhiêu; lựa chọn này gần như luôn sai.<br><strong>Vì sao các lựa chọn khác sai:</strong> Caching, Batch cho việc không cần realtime và đo trên nhiệm vụ hoàn thành đều là khuyến nghị đúng."},
  {"level": 2, "q": "Service NestJS dưới đây chạy agent. Rủi ro lớn nhất là gì?<pre><code>async run(messages: Anthropic.MessageParam[]) {\n  while (true) {\n    const res = await this.client.messages.create({ model: \"claude-opus-5\", max_tokens: 16000, tools, messages });\n    messages.push({ role: \"assistant\", content: res.content });\n    if (res.stop_reason === \"end_turn\") return res;\n    messages.push({ role: \"user\", content: await this.runTools(res) });\n  }\n}</code></pre>", "options": ["Không được dùng while trong TypeScript", "Phải dùng stream thay cho create", "messages phải khai báo bằng const", "Không có giới hạn số lượt: nếu Claude cứ gọi tool, vòng lặp chạy mãi và đốt chi phí"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Vòng while(true) chỉ thoát khi end_turn; cần đếm lượt và dừng ở MAX_TURNS.<br><strong>Vì sao các lựa chọn khác sai:</strong> while hợp lệ; streaming không phải yêu cầu; dùng let hay const cho mảng không phải vấn đề."},
  {"level": 2, "q": "Đoạn code sau đôi khi ném lỗi khó hiểu hoặc lưu dữ liệu rỗng. Nên sửa gì trước tiên?<pre><code>const res = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 2000, messages });\nconst data = JSON.parse((res.content[0] as any).text);\nawait prisma.extraction.create({ data });</code></pre>", "options": ["Bọc JSON.parse trong setTimeout", "Đổi model sang Haiku", "Tăng temperature", "Kiểm tra stop_reason (refusal, max_tokens) trước khi đọc content, và tìm khối text thay vì lấy content[0]"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Bài học: kiểm tra stop_reason trước khi đọc content; content là union nên phải lọc theo type.<br><strong>Vì sao các lựa chọn khác sai:</strong> setTimeout không giải quyết gì; đổi model và temperature không thay việc kiểm tra trạng thái."},
  {"level": 2, "q": "Khi người duyệt bấm \"Từ chối\", code dưới đây làm API báo lỗi ở lượt kế. Vì sao?<pre><code>for (const b of toolUses) {\n  if (DANGEROUS.has(b.name) &amp;&amp; !(await this.approvals.approved(b.id))) {\n    continue; // bỏ qua tool bị từ chối\n  }\n  results.push(await this.execute(b));\n}\nmessages.push({ role: \"user\", content: results });</code></pre>", "options": ["is_error chỉ dùng được với Python", "Khối tool_use bị từ chối không có tool_result tương ứng trong lượt user tiếp theo", "Không được dùng continue trong for...of", "Phải gửi lại toàn bộ system prompt"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mọi tool_use cần một tool_result; khi từ chối, trả tool_result với is_error: true và lý do.<br><strong>Vì sao các lựa chọn khác sai:</strong> is_error có trong mọi SDK; continue hợp lệ; system prompt không liên quan."},
  {"level": 2, "q": "Lớp retry dưới đây có lỗi logic nào?<pre><code>async function withRetry&lt;T&gt;(fn: () =&gt; Promise&lt;T&gt;, attempts = 3) {\n  for (let i = 0; i &lt; attempts; i++) {\n    try { return await fn(); }\n    catch (e) {\n      if (i === attempts - 1) throw e;\n      await sleep(1000 * 2 ** i); // retry mọi loại lỗi, kể cả ValidationError\n    }\n  }\n}</code></pre>", "options": ["Backoff phải giảm dần", "Không được dùng async/await trong vòng for", "attempts phải bằng 1", "Retry cả lỗi dữ liệu (ValidationError) vốn sẽ luôn thất bại, lãng phí thời gian và gọi API"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Chỉ retry lỗi tạm thời; lỗi đầu vào trả is_error ngay kèm hướng dẫn định dạng đúng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Backoff tăng dần là đúng; await trong for hợp lệ; 1 lần là không retry."},
  {"level": 2, "q": "Hai thông điệp lỗi tool dưới đây. Thông điệp nào giúp agent hành xử đúng hơn?<pre><code>// A\n{ type: \"tool_result\", tool_use_id: id, is_error: true, content: \"Error\" }\n\n// B\n{ type: \"tool_result\", tool_use_id: id, is_error: true,\n  content: \"Cổng thanh toán timeout sau 3 lần thử. KHÔNG gọi lại refund_order. Hãy báo khách sẽ có nhân viên liên hệ.\" }</code></pre>", "options": ["Thông điệp A vì ngắn", "Hai thông điệp tương đương", "Không cần thông điệp, chỉ cần is_error", "Thông điệp B: nói rõ đã thử mấy lần, có nên thử lại không và nên làm gì tiếp"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Ví dụ agent hoàn tiền: thông điệp \"timeout, đừng thử lại, hãy báo nhân viên\" chặn vòng lặp gọi lại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thông điệp mơ hồ khiến model gọi lại; hai thông điệp khác nhau về hướng dẫn; is_error không kèm nội dung khiến model đoán."},
  {"level": 2, "q": "Log cho thấy cache_read_input_tokens luôn bằng 0 dù system prompt dài được gửi lặp lại. Nguyên nhân khả dĩ nhất trong đoạn sau?<pre><code>system: [{\n  type: \"text\",\n  text: `Thời gian: ${new Date().toISOString()}\\n${INVOICE_RULES}\\n${JSON_SCHEMA}`,\n  cache_control: { type: \"ephemeral\" },\n}],</code></pre>", "options": ["cache_control phải đặt trong messages", "Model không hỗ trợ caching", "Chèn thời gian hiện tại vào đầu system prompt làm prefix thay đổi mỗi request, cache không bao giờ khớp", "max_tokens quá lớn"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Cache là khớp prefix; bất kỳ byte thay đổi nào như Date.now() hay UUID đều vô hiệu hoá phần sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> cache_control đặt ở system là hợp lệ; model hỗ trợ caching; max_tokens không ảnh hưởng."},
  {"level": 2, "q": "Cách bật caching nhanh nhất cho request dưới đây theo tài liệu SDK là gì?<pre><code>const res = await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 16000,\n  system: LONG_POLICY_DOC,\n  messages: [{ role: \"user\", content: question }],\n});</code></pre>", "options": ["Thêm header x-cache: true", "Thêm cache_control: { type: \"ephemeral\" } ở cấp top-level để tự cache khối cacheable cuối cùng", "Đặt temperature: 0", "Gọi batches.create thay vì messages.create"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Automatic caching dùng cache_control top-level; cũng có thể đặt thủ công trên từng khối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có header x-cache; temperature không bật cache; Batch là cơ chế giảm giá khác."},
  {"level": 2, "q": "Job xử lý kết quả Batch lưu vào PostgreSQL theo thứ tự mảng requests ban đầu. Vì sao đây là lỗi?<pre><code>const batch = await client.messages.batches.create({\n  requests: invoices.map((inv) =&gt; ({\n    custom_id: inv.id,\n    params: { model: \"claude-opus-5\", max_tokens: 4000, messages: [{ role: \"user\", content: inv.text }] },\n  })),\n});\n// ... sau khi ended\nlet i = 0;\nfor await (const r of await client.messages.batches.results(batch.id)) {\n  await save(invoices[i++].id, r); // ?\n}</code></pre>", "options": ["custom_id phải là số", "Batch không trả kết quả", "Kết quả batch có thể không theo thứ tự gửi; phải ghép theo custom_id", "Chỉ được tối đa 10 request mỗi batch"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Mỗi request có custom_id để đối chiếu; dựa vào thứ tự dễ gán nhầm hoá đơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> custom_id là chuỗi; batch có trả kết quả; giới hạn là tới 100.000 request."},
  {"level": 2, "q": "Hàm dưới đây tính chi phí trên mỗi nhiệm vụ hoàn thành. Với cost 0,04 USD, success 0,8, review 0,1 USD mỗi thất bại, kết quả xấp xỉ?<pre><code>function costPerSuccess(costPerRun: number, successRate: number, reviewPerFailure = 0) {\n  const runs = 1 / successRate;\n  const failures = runs - 1;\n  return costPerRun * runs + reviewPerFailure * failures;\n}</code></pre>", "options": ["0,04 USD", "0,075 USD", "0,05 USD", "0,14 USD"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> runs = 1/0,8 = 1,25; failures = 0,25; 0,04 × 1,25 + 0,1 × 0,25 = 0,05 + 0,025 = 0,075.<br><strong>Vì sao các lựa chọn khác sai:</strong> 0,04 là giá mỗi lần chạy; 0,05 bỏ quên chi phí xem xét; 0,14 cộng sai công thức."},
  {"level": 2, "q": "Cấu hình A: 0,05 USD/lần, thành công 90%. Cấu hình B: 0,03 USD/lần, thành công 50%. Chỉ xét token, cấu hình nào rẻ hơn trên mỗi nhiệm vụ hoàn thành?", "options": ["B vì mỗi lần chạy rẻ hơn", "Bằng nhau", "Không tính được nếu thiếu số token", "A (khoảng 0,056 USD so với 0,06 USD của B)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> A: 0,05/0,9 ≈ 0,056; B: 0,03/0,5 = 0,06. Request rẻ nhưng hay thất bại vẫn đắt hơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> So giá mỗi lần chạy là sai chỉ số; hai số khác nhau; đã đủ dữ liệu để tính."},
  {"level": 2, "q": "Script eval dưới đây kết luận \"effort low tốt bằng high\". Điểm yếu phương pháp chính là gì?<pre><code>const CASES = [[\"App crash khi login\", \"bug\"], [\"Thêm dark mode\", \"feature\"],\n  [\"Sửa typo README\", \"docs\"], [\"Làm sao deploy?\", \"question\"], [\"Nút lưu không chạy\", \"bug\"]];\nfor (const effort of [\"high\", \"low\"] as const) {\n  let ok = 0;\n  for (const [text, gold] of CASES) if ((await classify(text, effort)) === gold) ok++;\n  console.log(effort, ok / CASES.length);\n}</code></pre>", "options": ["Mỗi case chỉ chạy một lần và tập chỉ có 5 case dễ, không đủ để phân biệt hai cấu hình", "Không được dùng for...of", "Phải dùng Batch API cho eval", "effort không hợp lệ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Cần nhiều case (có cả case khó/mơ hồ) và chạy nhiều lần để có tỉ lệ đáng tin.<br><strong>Vì sao các lựa chọn khác sai:</strong> Cú pháp lặp hợp lệ; Batch là tuỳ chọn tiết kiệm, không phải điều kiện; low/high là effort hợp lệ."},
  {"level": 2, "q": "Grader dưới đây cho agent sửa bug đang chấm theo cách nào và có vấn đề gì?<pre><code>function grade(run: AgentRun) {\n  const expected = [\"Grep\", \"Read\", \"Edit\", \"Bash\"];\n  return JSON.stringify(run.toolSequence) === JSON.stringify(expected);\n}</code></pre>", "options": ["Chấm theo từng bước (phải gọi đúng chuỗi tool); phạt oan agent đi đường khác nhưng vẫn làm test pass", "Chấm theo kết quả cuối, không có vấn đề", "Chấm theo chi phí", "Chấm theo độ dài output"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Nên chấm kết quả cuối: chạy test suite sau khi agent xong.<br><strong>Vì sao các lựa chọn khác sai:</strong> Grader so khớp chuỗi tool chứ không kiểm test; không xét chi phí hay độ dài."},
  {"level": 2, "q": "Agent trích xuất trả JSON bị thiếu ngoặc đóng ở một số hoá đơn dài; stop_reason là \"max_tokens\". Cách xử lý đúng?<pre><code>if (res.stop_reason === \"max_tokens\") {\n  // ?\n}\nconst text = res.content.find((b) =&gt; b.type === \"text\")?.text ?? \"\";\nreturn JSON.parse(text);</code></pre>", "options": ["Phát hiện max_tokens, tăng max_tokens hoặc chia nhỏ nhiệm vụ; không parse output bị cắt", "Tự thêm dấu } vào cuối rồi parse", "Giảm max_tokens để model viết ngắn", "Bỏ qua các hoá đơn đó"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Output bị cắt không đáng tin; phải xử lý nguyên nhân.<br><strong>Vì sao các lựa chọn khác sai:</strong> Vá chuỗi có thể tạo dữ liệu sai; giảm max_tokens làm cắt nhiều hơn; bỏ qua làm mất dữ liệu."},
  {"level": 2, "q": "Hàm logStep dưới đây có vấn đề gì?<pre><code>function logStep(turn: number, res: Anthropic.Message) {\n  for (const b of res.content) {\n    if (b.type === \"tool_use\") {\n      logger.info(JSON.stringify({ turn, stop: res.stop_reason, tool: b.name, input: b.input }));\n      // input ví dụ: { cardNumber: \"4111...\", authToken: \"sk-...\" }\n    }\n  }\n}</code></pre>", "options": ["Không được dùng JSON.stringify", "Phải log ra file .txt", "Thiếu log stop_reason", "Ghi nguyên input tool, trong đó có thể có token/thẻ thanh toán, vào log; cần che hoặc rút gọn trường nhạy cảm"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Log cần đủ để debug nhưng không được chứa secret hay dữ liệu nhạy cảm; áp dụng redaction.<br><strong>Vì sao các lựa chọn khác sai:</strong> JSON.stringify là bình thường; định dạng file không quan trọng; stop_reason đã có trong log."},
  {"level": 2, "q": "Muốn thử effort \"medium\" cho trích xuất hoá đơn trong TypeScript. Tham số đặt ở đâu?<pre><code>const res = await client.messages.create({\n  model: \"claude-opus-5\",\n  max_tokens: 4000,\n  // effort đặt ở đâu?\n  messages: [{ role: \"user\", content: invoiceText }],\n});</code></pre>", "options": ["thinking: { budget_tokens: \"medium\" }", "effort: \"medium\" ở cấp header HTTP", "metadata: { effort: \"medium\" }", "output_config: { effort: \"medium\" }"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> effort nằm trong output_config (cùng chỗ với format cho structured output).<br><strong>Vì sao các lựa chọn khác sai:</strong> budget_tokens là cơ chế cũ, không nhận chuỗi và bị bỏ trên model mới; không có header effort; metadata không điều khiển effort."},
  {"level": 2, "q": "Vòng polling Batch sau dừng khi nào là đúng?<pre><code>let batch = await client.messages.batches.retrieve(id);\nwhile (/* điều kiện? */) {\n  await sleep(60_000);\n  batch = await client.messages.batches.retrieve(id);\n}</code></pre>", "options": ["Khi processing_status bằng \"succeeded\"", "Khi processing_status bằng \"ended\", rồi mới đọc kết quả", "Sau đúng 60 giây", "Khi request_counts.processing lớn hơn 0"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Batch kết thúc khi trạng thái ended; từng request có kết quả riêng (thành công/lỗi/hết hạn).<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có trạng thái succeeded ở cấp batch; thời gian cố định không đảm bảo xong; processing > 0 nghĩa là còn đang chạy."},
  {"level": 2, "q": "Workflow eval dưới đây cần làm job fail khi tỉ lệ đúng dưới 95%. Cách hợp lý?<pre><code>name: agent-eval\non:\n  pull_request:\n    paths: [\"packages/agents/prompts/**\", \"packages/agents/src/**\"]\njobs:\n  eval:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: pnpm/action-setup@v4\n      - run: pnpm install --frozen-lockfile\n      - run: pnpm --filter @acme/evals exec tsx src/run.ts --min-pass 0.95\n        env:\n          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}</code></pre>", "options": ["Script eval tính tỉ lệ và gọi process.exit(1) khi dưới ngưỡng để step fail, chặn merge qua required check", "Ghi tỉ lệ vào README", "Dùng continue-on-error: true", "Chạy eval sau khi merge"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Exit code khác 0 làm step fail; kết hợp branch protection để chặn PR làm giảm chất lượng.<br><strong>Vì sao các lựa chọn khác sai:</strong> README không chặn được gì; continue-on-error bỏ qua lỗi; chạy sau merge thì quá muộn."},
  {"level": 2, "q": "Model Prisma dưới đây dùng cho luồng phê duyệt tool nguy hiểm. Trường nào quan trọng nhất để resume đúng khi được duyệt?<pre><code>model PendingApproval {\n  id            Int      @id @default(autoincrement())\n  runId         String\n  toolUseId     String   @unique\n  toolName      String\n  input         Json\n  status        String   @default(\"pending\") // pending | approved | rejected\n  approverEmail String?\n  createdAt     DateTime @default(now())\n}</code></pre>", "options": ["createdAt", "toolUseId (cùng runId) để gửi tool_result đúng khối tool_use đang chờ", "approverEmail", "id tự tăng"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Khi resume, tool_result phải tham chiếu đúng tool_use_id; runId giúp nạp lại lịch sử hội thoại.<br><strong>Vì sao các lựa chọn khác sai:</strong> createdAt, email người duyệt và id nội bộ hữu ích cho audit nhưng không định danh tool_use."},
  {"level": 2, "q": "Lambda xử lý SQS gặp lỗi tạm thời ở vài message trong batch. Cách trả kết quả đúng để chỉ retry các message lỗi?<pre><code>export const handler = async (event: SQSEvent) =&gt; {\n  const batchItemFailures: { itemIdentifier: string }[] = [];\n  for (const record of event.Records) {\n    try { await extractInvoice(JSON.parse(record.body)); }\n    catch (e) {\n      if (isTransient(e)) batchItemFailures.push({ itemIdentifier: record.messageId });\n      else await markFailed(record, e);\n    }\n  }\n  return { batchItemFailures };\n};</code></pre>", "options": ["Ném lỗi để cả batch retry", "Nuốt lỗi và trả thành công", "Bật ReportBatchItemFailures và trả batchItemFailures chứa itemIdentifier của message lỗi", "Xoá message lỗi bằng tay"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Partial batch response tránh xử lý lại (và gọi model lại) các message đã thành công.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ném lỗi làm retry cả batch, tốn chi phí và có thể trùng; nuốt lỗi làm mất việc; xoá tay làm mất dữ liệu."},
  {"level": 2, "q": "Client Anthropic dưới đây được cấu hình cho worker. Hai option có tác dụng gì?<pre><code>const client = new Anthropic({ maxRetries: 3, timeout: 60_000 });</code></pre>", "options": ["maxRetries: số lần SDK tự retry lỗi tạm thời (như 429, 5xx) có backoff; timeout: thời gian tối đa mỗi request", "maxRetries: số lượt agent; timeout: TTL cache", "Cả hai chỉ dùng cho Batch API", "maxRetries: số tool tối đa; timeout: thời gian suy nghĩ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Retry tầng HTTP do SDK lo; vẫn cần MAX_TURNS cho vòng lặp và retry riêng cho tool gọi hệ thống ngoài.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không liên quan số lượt agent hay cache; áp dụng cho mọi request; không giới hạn số tool hay thinking."},
  {"level": 2, "q": "Vòng lặp nhận stop_reason \"pause_turn\" khi dùng web_search phía server. Đoạn xử lý nào đúng?<pre><code>if (res.stop_reason === \"pause_turn\") {\n  messages.push({ role: \"assistant\", content: res.content });\n  continue;\n}</code></pre>", "options": ["Coi là end_turn và trả kết quả", "Đẩy nội dung assistant vào messages rồi gọi lại API để model tiếp tục (không thêm tool_result)", "Gửi tool_result rỗng cho mọi khối", "Ném lỗi và dừng agent"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> pause_turn là tạm dừng có thể resume: gửi lại lượt assistant để tiếp tục.<br><strong>Vì sao các lựa chọn khác sai:</strong> Coi là xong sẽ trả câu trả lời cụt; không có tool_use của client để trả tool_result; dừng là mất công việc dở."},
  {"level": 2, "q": "Tool gọi API vận chuyển bên thứ ba đôi khi treo vô thời hạn làm cả vòng lặp đứng. Cách xử lý phù hợp ở tầng tool?<pre><code>async function trackShipment(code: string) {\n  const res = await fetch(`${CARRIER_API}/track/${code}`, {\n    signal: AbortSignal.timeout(5_000),\n  });\n  return res.json();\n}</code></pre>", "options": ["Đặt timeout cho lời gọi (AbortController/AbortSignal.timeout), hết thời gian thì trả is_error có hướng dẫn", "Tăng MAX_TURNS", "Để Claude tự quyết định chờ bao lâu", "Bỏ await để không phải chờ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Timeout là một loại giới hạn bắt buộc; lỗi được chuyển thành phản hồi rõ ràng cho model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Số lượt không giải quyết một lượt bị treo; model không kiểm soát được I/O của bạn; bỏ await làm mất kết quả."},
  {"level": 2, "q": "Dùng structured output như dưới cho trích xuất hoá đơn giúp giảm chi phí trên mỗi nhiệm vụ hoàn thành vì sao?<pre><code>output_config: {\n  format: {\n    type: \"json_schema\",\n    schema: {\n      type: \"object\",\n      properties: {\n        invoiceNo: { type: \"string\" },\n        total: { type: \"number\" },\n        vatRate: { type: \"number\" },\n      },\n      required: [\"invoiceNo\", \"total\", \"vatRate\"],\n      additionalProperties: false,\n    },\n  },\n},</code></pre>", "options": ["Structured output miễn phí token", "Nó bật Batch tự động", "Nó tắt thinking", "Output luôn khớp schema nên giảm lỗi parse và số lần phải chạy lại"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Ít thất bại hơn nghĩa là ít lần chạy lại; chi phí trên mỗi hoá đơn đúng giảm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Token vẫn tính phí; không bật Batch; không tắt thinking."},
  {"level": 2, "q": "Model Prisma nào dưới đây phục vụ tốt nhất việc quan sát và tính chi phí agent?<pre><code>model AgentStep {\n  id              String   @id @default(cuid())\n  runId           String\n  turn            Int\n  tool            String?\n  stopReason      String\n  inputTokens     Int\n  outputTokens    Int\n  cacheReadTokens Int      @default(0)\n  latencyMs       Int\n  createdAt       DateTime @default(now())\n  @@index([runId])\n}</code></pre>", "options": ["Chỉ lưu câu trả lời cuối vào một cột text", "Lưu toàn bộ header HTTP gồm API key", "Chỉ lưu tổng số request mỗi ngày", "Mỗi AgentStep lưu runId, turn, tool, stopReason, inputTokens, outputTokens, cacheReadTokens, latencyMs"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Dữ liệu theo từng bước cho phép debug, tính chi phí trên nhiệm vụ và phát hiện vòng lặp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ câu cuối không giải thích quá trình; không lưu secret; số request/ngày quá thô."},
  {"level": 2, "q": "200.000 hoá đơn cần trích xuất trước 8 giờ sáng, không ai chờ kết quả realtime. Đòn bẩy đầu tiên nên dùng?", "options": ["Batch API kết hợp cache phần hướng dẫn và schema", "Fast mode", "Tăng effort lên max", "Streaming"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Không cần realtime → Batch giảm khoảng 50%; prefix chung được cache để giảm thêm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Fast mode đắt hơn để đổi lấy tốc độ; tăng effort tốn thêm token; streaming không giảm giá."},
  {"level": 2, "q": "Chatbot hỗ trợ khách hàng trong Next.js cần phản hồi trong vài giây. Vì sao Batch API không phù hợp?", "options": ["Batch là bất đồng bộ, có thể mất tới 24 giờ, không đáp ứng yêu cầu độ trễ", "Batch không hỗ trợ tiếng Việt", "Batch không cho dùng tool", "Batch đắt hơn request thường"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Batch đổi độ trễ lấy giá rẻ; hợp việc chạy nền.<br><strong>Vì sao các lựa chọn khác sai:</strong> Batch hỗ trợ mọi ngôn ngữ và mọi tính năng Messages API; Batch rẻ hơn chứ không đắt hơn."},
  {"level": 2, "q": "Trong request dưới đây, sắp xếp nội dung thế nào để tối đa cache hit?<pre><code>system: [\n  { type: \"text\", text: userQuestion },          // (1)\n  { type: \"text\", text: RETURN_POLICY_40_PAGES }, // (2)\n],</code></pre>", "options": ["Phần ổn định (chính sách, schema, tool) đặt trước; phần thay đổi (câu hỏi, dữ liệu người dùng) đặt sau cùng", "Câu hỏi người dùng đặt đầu system prompt", "Xáo trộn thứ tự tool mỗi request", "Thêm request ID vào đầu prompt"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Cache khớp theo prefix; nội dung thay đổi đặt sau để prefix giữ nguyên giữa các request.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đặt nội dung thay đổi lên đầu phá prefix; đổi thứ tool hay thêm ID đều là \"silent invalidator\"."},
  {"level": 2, "q": "Service ghép danh sách tool từ nhiều module NestJS như dưới, thứ tự có thể đổi giữa các lần khởi động pod. Ảnh hưởng tới chi phí?<pre><code>const tools = [...this.registry.values()].flatMap((m) =&gt; m.tools());\n// registry là Map được đăng ký theo thứ tự module khởi tạo xong</code></pre>", "options": ["Không ảnh hưởng vì tool không nằm trong prompt", "Giảm chi phí vì tool mới luôn rẻ hơn", "Thứ tự tool thay đổi làm prefix khác nhau nên cache giữa các pod/lần deploy không khớp; nên sắp xếp tool theo tên cố định", "Làm API trả lỗi 400"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Định nghĩa tool là một phần của prefix được cache; thứ tự phải xác định.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tool có trong prefix; thứ tự không đổi giá; API không báo lỗi vì thứ tự."},
  {"level": 2, "q": "Đoạn sau gate hoàn tiền theo ngưỡng. Hành vi đúng khi amount = 800.000đ là gì?<pre><code>async refundOrder(input: { orderId: string; amount: number }, toolUseId: string) {\n  if (input.amount &gt; 500_000) {\n    await this.prisma.pendingApproval.create({ data: { toolUseId, toolName: \"refund_order\", input, runId: this.runId } });\n    return { content: \"Yêu cầu hoàn tiền đang chờ nhân viên duyệt.\", is_error: false };\n  }\n  return { content: JSON.stringify(await this.payments.refund(input)) };\n}</code></pre>", "options": ["Hoàn tiền ngay vì agent đã quyết định", "Ném exception làm hỏng request", "Tạo bản ghi chờ duyệt và trả tool_result báo \"đang chờ nhân viên duyệt\", chưa gọi cổng thanh toán", "Tự giảm số tiền xuống 500.000đ"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Ví dụ thật: hoàn tiền trên 500.000đ cần nhân viên bấm duyệt; agent nhận trạng thái rõ ràng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hoàn ngay bỏ qua kiểm soát; ném lỗi không cho model biết cần làm gì; tự sửa số tiền là sai nghiệp vụ."},
  {"level": 2, "q": "Bộ phát hiện lặp dưới đây dùng để làm gì?<pre><code>const seen = new Map&lt;string, number&gt;();\nfunction guard(b: Anthropic.ToolUseBlock) {\n  const key = b.name + \":\" + JSON.stringify(b.input);\n  const n = (seen.get(key) ?? 0) + 1;\n  seen.set(key, n);\n  if (n &gt;= 3) throw new AgentLoopError(`Lặp ${b.name} ${n} lần`);\n}</code></pre>", "options": ["Cache kết quả tool để giảm token", "Dừng sớm khi agent gọi cùng tool với cùng input nhiều lần, thay vì đợi chạm MAX_TURNS", "Chặn tool nguy hiểm", "Đo độ trễ"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Circuit breaker theo chữ ký tool+input bắt vòng lặp kiểu 37 lần gọi lại refund_order.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không phải cache; không phân loại tool nguy hiểm; không đo thời gian."},
  {"level": 2, "q": "Dòng log JSON sau trên Lambda có tác dụng gì với CloudWatch?<pre><code>console.log(JSON.stringify({\n  _aws: {\n    Timestamp: Date.now(),\n    CloudWatchMetrics: [{\n      Namespace: \"Agents\", Dimensions: [[\"Agent\"]],\n      Metrics: [{ Name: \"InputTokens\", Unit: \"Count\" }, { Name: \"OutputTokens\", Unit: \"Count\" }],\n    }],\n  },\n  Agent: \"invoice-extractor\",\n  InputTokens: res.usage.input_tokens,\n  OutputTokens: res.usage.output_tokens,\n}));</code></pre>", "options": ["Theo Embedded Metric Format, CloudWatch tự trích metric InputTokens/OutputTokens theo dimension Agent từ log", "Chỉ là log văn bản, không tạo metric", "Gửi cảnh báo email", "Tăng timeout Lambda"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> EMF cho phép phát metric qua log mà không gọi PutMetricData; dùng để vẽ dashboard chi phí.<br><strong>Vì sao các lựa chọn khác sai:</strong> Khối _aws đúng định dạng thì CloudWatch tạo metric; email cần alarm/SNS; không liên quan timeout."},
  {"level": 2, "q": "Tool refund_order có thể được gọi lại sau timeout (tầng tool retry). Làm sao tránh hoàn tiền hai lần?<pre><code>await this.payments.refund({\n  orderId: input.orderId,\n  amount: input.amount,\n  idempotencyKey: `refund-${toolUseId}`,\n});</code></pre>", "options": ["Tắt retry hoàn toàn", "Giảm MAX_TURNS", "Gửi idempotency key ổn định (ví dụ dựa trên tool_use_id hoặc orderId) cho cổng thanh toán", "Dặn model gọi đúng một lần"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Idempotency key để cổng thanh toán nhận ra yêu cầu trùng; retry vẫn an toàn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt retry làm lỗi tạm thời thành thất bại; MAX_TURNS không ngăn retry ở tầng tool; lời dặn model không đảm bảo."},
  {"level": 2, "q": "Eval chạy mỗi case 5 lần. Cách báo cáo nào phản ánh đúng độ tin cậy cho agent production?", "options": ["Tỉ lệ thành công trên tổng số lần chạy (và số case luôn đúng cả 5 lần)", "Coi case là đúng nếu ít nhất 1 trong 5 lần đúng", "Chỉ báo lần chạy tốt nhất", "Lấy trung bình độ dài output"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Người dùng production gặp một lần chạy bất kỳ, nên tỉ lệ trên mọi lần chạy mới phản ánh thực tế.<br><strong>Vì sao các lựa chọn khác sai:</strong> \"Ít nhất 1 lần đúng\" thổi phồng độ tin cậy; chọn lần tốt nhất là thiên lệch; độ dài không phải chất lượng."},
  {"level": 2, "q": "Đội tinh chỉnh prompt nhiều vòng trên 100 case và báo cáo 98% trên chính 100 case đó. Vấn đề là gì?", "options": ["100 case là quá nhiều", "Không có vấn đề gì", "Điểm bị thổi phồng do khớp quá mức với tập tinh chỉnh; cần tập test riêng chưa dùng để tinh chỉnh", "Phải dùng model khác để chấm"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tách dev/test là nguyên tắc cơ bản của eval.<br><strong>Vì sao các lựa chọn khác sai:</strong> Số lượng không phải vấn đề; khẳng định không sao là bỏ qua rò rỉ; đổi grader không giải quyết rò rỉ."},
  {"level": 2, "q": "Agent sửa bug trong apps/api. Cách chấm nào khách quan và rẻ nhất?", "options": ["Nhờ LLM đọc diff và cho điểm 1–10", "Đếm số file agent sửa", "Chạy test suite (ví dụ pnpm --filter api test) sau khi agent xong; pass là đạt", "Hỏi agent tự đánh giá"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Kiểm tra xác định (deterministic) được ưu tiên khi có; LLM judge chỉ dùng khi không có tiêu chí tự động.<br><strong>Vì sao các lựa chọn khác sai:</strong> LLM judge tốn tiền và cần hiệu chỉnh; số file không phản ánh đúng sai; tự đánh giá không khách quan."},
  {"level": 2, "q": "Vòng lặp dưới đây dừng theo ngân sách token tự đặt. Tác dụng so với chỉ dùng max_tokens?<pre><code>let totalTokens = 0;\nconst BUDGET = 200_000;\nfor (let turn = 0; turn &lt; MAX_TURNS; turn++) {\n  const res = await client.messages.create(params);\n  totalTokens += res.usage.input_tokens + res.usage.output_tokens;\n  if (totalTokens &gt; BUDGET) throw new BudgetExceededError(totalTokens);\n  // ...\n}</code></pre>", "options": ["Không khác gì max_tokens", "Giới hạn tổng chi phí của cả nhiệm vụ nhiều lượt; max_tokens chỉ giới hạn từng response", "Làm model tự biết ngân sách", "Giảm giá mỗi token"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đếm token tích luỹ là trần cứng phía ứng dụng. Muốn model tự điều tiết thì dùng task budget (beta).<br><strong>Vì sao các lựa chọn khác sai:</strong> max_tokens là theo response; model không thấy biến totalTokens của bạn; không đổi đơn giá."},
  {"level": 2, "q": "Tool get_customer trả về toàn bộ bản ghi Prisma (cả lịch sử đơn, ghi chú dài). Tối ưu \"miễn phí\" nào hợp lý?<pre><code>const c = await prisma.customer.findUnique({\n  where: { id },\n  include: { orders: true, notes: true },\n});\nreturn JSON.stringify(c);</code></pre>", "options": ["Chỉ select các trường agent cần và giới hạn số bản ghi, để giảm token input ở các lượt sau", "Chuyển sang model rẻ hơn", "Giảm effort xuống low", "Tắt tool get_customer"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Kết quả tool đi vào context mọi lượt sau; cắt token thừa là tối ưu không đánh đổi chất lượng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model/effort là đánh đổi, làm sau; tắt tool làm hỏng chức năng."},
  {"level": 2, "q": "Vì sao \"output gọn\" là một đòn bẩy chi phí đáng kể?", "options": ["Token output thường đắt hơn token input nhiều lần, nên yêu cầu định dạng ngắn/structured giảm chi phí rõ", "Vì output không tính tiền", "Vì output ngắn luôn chính xác hơn", "Vì output dài bị API từ chối"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Giảm output thừa (giải thích dài không cần) là tối ưu miễn phí nếu vẫn đủ thông tin.<br><strong>Vì sao các lựa chọn khác sai:</strong> Output có tính tiền; ngắn không đồng nghĩa chính xác; API không từ chối output dài trong giới hạn."},
  {"level": 2, "q": "Bảng eval dưới đây. Ngưỡng chất lượng 95%. Chọn cấu hình nào?<pre><code>effort   accuracy   cost/run (USD)\nhigh     99.4%      0.0120\nmedium   99.0%      0.0080\nlow      91.0%      0.0050</code></pre>", "options": ["high vì chính xác nhất", "low vì rẻ nhất mỗi lần", "medium: đạt ngưỡng với chi phí trên mỗi hoá đơn đúng thấp nhất trong các cấu hình đạt", "Không chọn được"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chọn cấu hình rẻ nhất vẫn đạt ngưỡng; tính trên kết quả đúng: medium ≈ 0,0081, high ≈ 0,0121.<br><strong>Vì sao các lựa chọn khác sai:</strong> high đắt hơn mà không cần; low dưới ngưỡng; đủ dữ liệu để quyết định."},
  {"level": 2, "q": "Agent CI \"sửa test flaky\" thường báo \"đã xong\" nhưng test vẫn fail. Bổ sung nào hiệu quả nhất?", "options": ["Thêm câu \"hãy chắc chắn\" vào prompt", "Tăng max_tokens", "Đổi sang model khác ngay", "Bắt buộc bước kiểm chứng: agent phải chạy lại test nhiều lần và chỉ báo xong khi pass; grader cũng chạy test độc lập"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tín hiệu kiểm chứng khách quan cho agent tự sửa; grader độc lập tránh tin lời agent.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lời nhắc không phải kiểm chứng; max_tokens không liên quan; đổi model khi chưa có eval là đánh đổi mù."},
  {"level": 3, "q": "Công ty kế toán trích xuất 200.000 hoá đơn mỗi đêm bằng request realtime, model mạnh, effort cao. Kế hoạch giảm chi phí đúng thứ tự nhất?", "options": ["Đổi ngay sang model rẻ nhất rồi xem khách có phàn nàn không", "Cache hướng dẫn + schema, cắt token thừa, chuyển sang Batch; sau đó eval 500 hoá đơn có đáp án với các mức effort và chọn mức rẻ nhất đạt ngưỡng", "Giảm max_tokens xuống 200", "Chia routing ba model ngay từ đầu"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đi từ đòn bẩy miễn phí tới đánh đổi có đo đạc, đúng như ví dụ thật trong bài.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đổi model khi chưa eval là bẫy; max_tokens thấp gây cắt JSON và chạy lại; routing sớm phức tạp và mất cache."},
  {"level": 3, "q": "Đội đề xuất routing: Haiku cho hoá đơn đơn giản, Opus cho hoá đơn khó. System prompt 30K token được cache. Cảnh báo quan trọng nhất trước khi làm?", "options": ["Cache gắn với model nên hai model phải ghi cache riêng; nên đo phương án một model với effort thấp hơn trước rồi mới so với routing", "Haiku không đọc được tiếng Việt", "Routing luôn rẻ hơn nên làm ngay", "Opus không hỗ trợ caching"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Bài học nhấn mạnh routing đánh đổi mất cache; cần so trên chi phí mỗi nhiệm vụ hoàn thành.<br><strong>Vì sao các lựa chọn khác sai:</strong> Haiku xử lý tiếng Việt; routing không chắc rẻ hơn; Opus hỗ trợ caching."},
  {"level": 3, "q": "Agent hoàn tiền gọi refund_order 37 lần trong một phiên vì cổng thanh toán timeout. Tổ hợp khắc phục đầy đủ nhất?", "options": ["Chỉ tăng timeout của cổng thanh toán", "Chuyển sang model mạnh hơn", "MAX_TURNS, tool_result is_error với hướng dẫn \"đừng thử lại, báo nhân viên\", retry có backoff ở tầng tool, idempotency key, phê duyệt cho khoản lớn", "Xoá tool refund_order"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Mỗi biện pháp chặn một lớp nguyên nhân: vòng lặp, phản hồi mơ hồ, lỗi thoáng qua, hoàn trùng, rủi ro tài chính.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ tăng timeout không chặn được vòng lặp; model mạnh vẫn lặp nếu phản hồi mơ hồ; xoá tool làm mất tính năng."},
  {"level": 3, "q": "Sau khi tinh chỉnh, agent đạt 92% trên tập dev nhưng chỉ 80% trên tập test. Kết luận và hành động đúng?", "options": ["Gộp test vào dev để có điểm cao hơn", "Bỏ tập test vì không ổn định", "Báo cáo 92% cho quản lý", "Prompt đang khớp quá mức với dev; phân tích lỗi trên test theo nhóm, bổ sung case đa dạng vào dev, giữ test để báo cáo"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Khoảng cách dev–test là dấu hiệu overfit; cải thiện độ tổng quát và giữ tập test độc lập.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gộp tập làm mất thước đo trung thực; bỏ test là che vấn đề; báo cáo 92% là sai lệch."},
  {"level": 3, "q": "Chat hỗ trợ trong apps/web: yêu cầu p95 dưới 3 giây, lượng truy cập tăng gấp 3, ngân sách giữ nguyên. Hướng tối ưu hợp lý nhất?", "options": ["Chuyển toàn bộ sang Batch API", "Tăng effort lên max để giảm hỏi lại", "Cache system prompt và tài liệu chính sách, cắt kết quả tool thừa, streaming để cải thiện cảm nhận; sau đó eval để quyết định có routing câu đơn giản sang Haiku", "Bỏ tool tra đơn để giảm token"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Ràng buộc độ trễ loại trừ Batch; tối ưu miễn phí trước, đánh đổi sau khi đo.<br><strong>Vì sao các lựa chọn khác sai:</strong> Batch không đáp ứng realtime; effort max tăng chi phí và độ trễ; bỏ tool làm hỏng chức năng."},
  {"level": 3, "q": "Agent DevOps có tool chạy prisma migrate deploy trên RDS production. Thiết kế an toàn nhất?", "options": ["Cho agent chạy migrate trực tiếp vì đã có MAX_TURNS", "Agent chỉ tạo kế hoạch/PR migration; việc apply lên production qua pipeline GitHub Actions có environment protection (người duyệt) với IAM role riêng", "Dặn agent \"cẩn thận với production\"", "Chạy migrate trên production rồi rollback nếu lỗi"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Thay đổi schema production khó đảo ngược, cần người duyệt và tách quyền.<br><strong>Vì sao các lựa chọn khác sai:</strong> MAX_TURNS không ngăn một lệnh phá huỷ; lời dặn không phải kiểm soát; rollback schema có dữ liệu thường không đơn giản."},
  {"level": 3, "q": "Lambda trích xuất hoá đơn đọc từ SQS. Một số hoá đơn hỏng luôn làm model trả lỗi, bị retry mãi, tốn tiền. Cấu hình nào giải quyết?", "options": ["Tăng visibility timeout lên 12 giờ", "Redrive policy với maxReceiveCount hợp lý đưa message lỗi sang DLQ, kèm alarm CloudWatch trên DLQ; lỗi dữ liệu thì đánh dấu thất bại ngay", "Tăng memory Lambda", "Tắt SQS, gọi trực tiếp"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Poison message cần được cách ly; phân biệt lỗi vĩnh viễn và tạm thời để không retry vô ích.<br><strong>Vì sao các lựa chọn khác sai:</strong> Visibility timeout dài chỉ trì hoãn retry; memory không sửa dữ liệu hỏng; bỏ SQS mất khả năng đệm và retry có kiểm soát."},
  {"level": 3, "q": "Hai cấu hình agent hỗ trợ: A 0,04 USD/lần, thành công 95%; B 0,02 USD/lần, thành công 60%. Mỗi lần thất bại cần nhân viên xem xét tốn 0,10 USD và làm khách chờ lâu hơn. Chọn?", "options": ["B, vì rẻ hơn một nửa mỗi lần chạy", "B, vì chỉ tính token thì rẻ hơn", "A, vì chi phí trên mỗi nhiệm vụ hoàn thành (≈ 0,047 USD) thấp hơn B (≈ 0,10 USD) khi tính chi phí con người, và độ trễ tốt hơn", "Không khác biệt"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Bài 4 của bài học: cộng chi phí xem xét thất bại, A thắng rõ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giá mỗi lần chạy là chỉ số sai; chỉ tính token bỏ qua chi phí thật; hai số khác nhau đáng kể."},
  {"level": 3, "q": "Giờ cao điểm, worker agent trên ECS nhận nhiều lỗi 429. Cách xử lý đúng nhất?", "options": ["Retry ngay lập tức vô hạn", "Để model tự gọi lại trong vòng lặp agent", "Tạo thêm API key để vượt giới hạn", "Để SDK retry có backoff với số lần giới hạn, đưa việc vào SQS và giới hạn concurrency của worker theo rate limit"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Rate limit là tín hiệu giảm tốc; hàng đợi + giới hạn concurrency làm mượt tải.<br><strong>Vì sao các lựa chọn khác sai:</strong> Retry dồn dập làm nặng thêm; 429 là lỗi HTTP, model không xử lý; lách giới hạn bằng nhiều key vi phạm chính sách và không bền."},
  {"level": 3, "q": "Pipeline tự động nhận stop_reason \"refusal\" ở một số yêu cầu. Cách xử lý chuẩn?", "options": ["Retry cùng request 10 lần", "Dừng xử lý yêu cầu đó, log stop_details, chuyển hàng đợi cho người xem xét; không lặp lại cùng request", "Coi output rỗng là kết quả hợp lệ", "Viết lại prompt để lách chính sách"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> refusal là tín hiệu cần con người; dữ liệu log giúp phân tích nguyên nhân.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lặp lại cùng request tốn chi phí; output rỗng không phải kết quả; lách chính sách là sai."},
  {"level": 3, "q": "Agent sinh file migration dài bị stop_reason \"max_tokens\" ở giữa. Phương án tốt nhất?", "options": ["Chạy lại y hệt và hy vọng ngắn hơn", "Ghép tạm output rồi commit", "Giảm effort xuống low", "Tăng max_tokens (dùng streaming cho output dài) hoặc chia nhiệm vụ thành phần nhỏ; không chấp nhận file bị cắt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Output bị cắt là thất bại; cần tăng trần hoặc giảm quy mô mỗi bước.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy lại y hệt dễ bị cắt tiếp; commit file cắt dở gây lỗi; giảm effort không đảm bảo ngắn và có thể giảm chất lượng."},
  {"level": 3, "q": "Agent refactor dài nhiều lượt, đôi khi dùng hết token cho phần đầu và làm ẩu phần cuối. Công cụ nào nhắm đúng vấn đề này nhất?", "options": ["Task budget (beta): cho model biết ngân sách token của cả nhiệm vụ để tự phân bổ, kết hợp trần cứng ở ứng dụng", "Giảm max_tokens mỗi response", "Tăng temperature", "Tắt thinking"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Khác max_tokens, task budget là thông tin model thấy được và dùng để tự điều tiết.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giảm max_tokens chỉ gây cắt; temperature và tắt thinking không giúp phân bổ công sức."},
  {"level": 3, "q": "Sự cố: agent đã xoá một bản ghi khách hàng nhưng không ai giải thích được vì sao. Bài học rút ra và thay đổi ưu tiên nhất?", "options": ["Tắt log để giảm chi phí CloudWatch", "Chỉ dặn agent không xoá", "Đổi model", "Bổ sung log từng bước (tool, input, output rút gọn, stop_reason) có runId, và đặt thao tác xoá vào nhóm cần phê duyệt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> \"Giới – Kiểm – Duyệt – Log\": thiếu log thì không truy vết được, thiếu duyệt thì hành động không đảo ngược xảy ra.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt log làm tình hình tệ hơn; lời dặn không phải kiểm soát; đổi model không giải quyết khả năng truy vết."},
  {"level": 3, "q": "Eval 10 lần chạy: cấu hình A đúng 9/10, B đúng 8/10. PM muốn chọn A vì \"tốt hơn 10%\". Phản hồi đúng?", "options": ["Đồng ý, A tốt hơn rõ ràng", "Chọn B vì chắc chắn rẻ hơn", "Mẫu quá nhỏ để kết luận; tăng số case và số lần chạy trước khi quyết định, đồng thời so chi phí mỗi nhiệm vụ hoàn thành", "Bỏ eval, chọn theo cảm nhận"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Chênh lệch 1/10 nằm trong dao động ngẫu nhiên; cần dữ liệu lớn hơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Kết luận từ 10 mẫu là vội; chưa biết B rẻ hơn; bỏ eval đi ngược nguyên tắc."},
  {"level": 3, "q": "Eval đầy đủ (1.000 case × 3 lần) tốn nhiều tiền nếu chạy trên mọi PR. Chiến lược CI cân bằng nhất?<pre><code>on:\n  pull_request:\n    paths: [\"packages/agents/**\"]\n  schedule:\n    - cron: \"0 18 * * *\"   # 01:00 giờ Việt Nam\njobs:\n  eval:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pnpm install --frozen-lockfile\n      - run: |\n          if [ \"${{ github.event_name }}\" = \"schedule\" ]; then\n            pnpm --filter @acme/evals exec tsx src/run.ts --suite full --batch\n          else\n            pnpm --filter @acme/evals exec tsx src/run.ts --suite smoke --min-pass 0.95\n          fi</code></pre>", "options": ["Chạy bộ đầy đủ trên mọi commit", "Không chạy eval trong CI", "Chỉ chạy eval khi có khách phàn nàn", "PR đổi prompt/agent chạy bộ smoke nhỏ có ngưỡng; bộ đầy đủ chạy nightly qua Batch API, báo cáo xu hướng"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Phân tầng eval cân bằng tốc độ phản hồi và chi phí; Batch giảm giá cho bộ lớn không cần realtime.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy đầy đủ mọi commit tốn kém; bỏ eval làm mất lưới an toàn; chờ khách phàn nàn là quá muộn."},
  {"level": 3, "q": "Agent nội bộ được gọi khoảng mỗi 10 phút với cùng system prompt 50K token; cache TTL mặc định 5 phút luôn hết hạn. Phương án hợp lý?<pre><code>system: [{\n  type: \"text\",\n  text: INTERNAL_KB_50K,\n  cache_control: { type: \"ephemeral\", ttl: \"1h\" },\n}],</code></pre>", "options": ["Tắt caching vì không hiệu quả", "Gửi request rỗng mỗi 4 phút để giữ cache vô hạn không tốn gì", "Chuyển sang Batch", "Dùng cache_control với ttl \"1h\" cho khối ổn định; ghi đắt hơn TTL 5 phút nhưng được đọc lại nhiều lần trong giờ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> TTL 1 giờ khớp nhịp gọi; cần tính đánh đổi giữa giá ghi và số lần đọc.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt caching bỏ lỡ tiết kiệm; request giữ cache vẫn tốn phí; Batch không hợp nếu cần phản hồi ngay."},
  {"level": 3, "q": "Eval phân loại: Haiku 97%, Opus 99%, ngưỡng 95%, 1 triệu request/tháng; sai sót nhỏ có thể sửa sau. Quyết định hợp lý nhất?", "options": ["Dùng Opus cho mọi request", "Dùng Haiku, chuyển các case độ tin cậy thấp hoặc mơ hồ lên Opus, giám sát tỉ lệ đúng bằng mẫu kiểm định hằng tuần", "Dùng Haiku và bỏ theo dõi", "Luân phiên model theo ngày"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đạt ngưỡng với chi phí thấp; escalation giữ chất lượng ở phần khó; giám sát bắt trôi chất lượng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Opus cho tất cả tốn kém không cần thiết; bỏ theo dõi rủi ro; luân phiên không có cơ sở."},
  {"level": 3, "q": "Agent tự động tạo PR sửa lỗi bảo mật dependency cho 40 service. Cần bật/tắt nhanh khi phát hiện hành vi bất thường. Thiết kế nào?", "options": ["Xoá repo agent khi có sự cố", "Chờ deploy bản mới để tắt", "Kill switch (feature flag hoặc tham số SSM) được đọc đầu mỗi run và trước mỗi tool ghi; mặc định tắt quyền ghi khi không đọc được cờ", "Dặn agent tự dừng khi thấy bất thường"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Cơ chế tắt ngoài agent, kiểm tra thường xuyên và fail-closed giới hạn thời gian sự cố.<br><strong>Vì sao các lựa chọn khác sai:</strong> Xoá repo là cực đoan và chậm; deploy lại mất thời gian; model không đáng tin để tự phát hiện bất thường."},
  {"level": 3, "q": "Luồng hoàn tiền cần quản lý duyệt qua trang admin Next.js, có thể sau vài giờ. Agent chạy trong NestJS. Thiết kế đúng?", "options": ["Giữ request HTTP mở vài giờ", "Lưu messages + tool_use chờ duyệt vào PostgreSQL, kết thúc lượt; khi admin duyệt qua API, nạp lại lịch sử, chạy tool, gửi tool_result và tiếp tục vòng lặp", "Cho agent tự duyệt khi quá 1 giờ", "Tạo agent mới từ đầu sau khi duyệt"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trạng thái lưu bền cho phép resume an toàn qua deploy/scale; tool_result gắn đúng tool_use_id.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giữ kết nối lâu không bền; tự duyệt vi phạm quy trình; chạy lại từ đầu mất ngữ cảnh và có thể lặp hành động."},
  {"level": 3, "q": "Worker có ba tầng retry: SDK maxRetries 5, tool retry 5 lần, và prompt bảo model \"thử lại nếu lỗi\" tối đa 5 lần. Vấn đề?", "options": ["Không có vấn đề, càng nhiều retry càng tin cậy", "Retry nhân lên (tới hàng trăm lần gọi) gây bão retry, tăng chi phí và độ trễ; nên giới hạn tổng và chỉ retry ở tầng phù hợp", "Chỉ tầng SDK có tác dụng", "Retry của model là rẻ nhất"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mỗi tầng nhân với tầng dưới; lỗi kéo dài biến thành tải lớn lên hệ thống đang lỗi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Nhiều retry không đồng nghĩa tin cậy; tầng tool cũng có tác dụng; retry qua model tốn lượt và token nhất."},
  {"level": 3, "q": "Agent tổng hợp báo cáo tháng mất khoảng 25 phút. Đội định chạy trên Lambda được EventBridge kích hoạt. Kiến trúc tốt hơn?", "options": ["Lambda với timeout 25 phút", "Chạy trên máy dev qua cron", "EventBridge Scheduler kích hoạt ECS Fargate task (hoặc Step Functions điều phối các bước ngắn), vì Lambda giới hạn 15 phút", "Chia prompt thành 25 Lambda song song không phối hợp"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tác vụ dài cần runtime không có trần 15 phút hoặc điều phối theo bước.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lambda không cho timeout quá 15 phút; máy dev không đáng tin; song song không phối hợp làm mất ngữ cảnh chung."},
  {"level": 3, "q": "Sau tối ưu, chi phí mỗi request giảm 30% nhưng tỉ lệ nhiệm vụ thành công giảm từ 95% xuống 70%. Đánh giá?", "options": ["Tốt hơn vì request rẻ hơn 30%", "Tổng thể tệ hơn: chi phí trên mỗi nhiệm vụ hoàn thành gần như không giảm, trong khi tỉ lệ thất bại tăng gấp 6 lần", "Không đổi", "Tốt hơn vì ít token hơn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lấy chi phí cũ là 1: trước 1/0,95 ≈ 1,05, sau 0,7/0,70 = 1,0 mỗi nhiệm vụ hoàn thành; thất bại tăng từ 5% lên 30% kéo theo chi phí xử lý và trải nghiệm kém hơn nhiều.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giá mỗi request là chỉ số sai; kết quả thay đổi rõ; ít token không phải mục tiêu cuối."},
  {"level": 3, "q": "Đội dùng LLM-as-judge chấm chất lượng tóm tắt ticket. Làm sao tin được điểm của judge?", "options": ["Hiệu chỉnh judge với một mẫu có nhãn của người, đo mức đồng thuận, dùng rubric rõ và kiểm tra lại định kỳ", "Tin tuyệt đối vì judge là model mạnh", "Dùng cùng prompt với agent để judge hiểu ngữ cảnh", "Chỉ chấm các case agent làm đúng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Judge cũng là mô hình có sai số; cần đối chiếu với con người.<br><strong>Vì sao các lựa chọn khác sai:</strong> Model mạnh vẫn có thiên lệch; dùng chung prompt tạo thiên vị; chọn case làm lệch mẫu."},
  {"level": 3, "q": "Agent sửa code trực tiếp trên nhánh main khi chạy trong CI. Cách đảm bảo khả năng rollback tốt nhất?", "options": ["Agent làm việc trên nhánh riêng, commit theo từng bước, mở PR để review; main chỉ nhận thay đổi qua merge có kiểm tra", "Tắt branch protection để agent push nhanh", "Sao lưu repo thủ công mỗi tuần", "Dặn agent không làm sai"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Nhánh + commit từng bước là checkpoint tự nhiên, dễ revert; PR thêm lớp duyệt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt bảo vệ làm tăng rủi ro; sao lưu tuần quá thưa; lời dặn không phải kiểm soát."},
  {"level": 3, "q": "Log CloudWatch của agent chứa số điện thoại và địa chỉ khách hàng từ kết quả tool. Hướng xử lý đúng?", "options": ["Tắt toàn bộ log", "Giữ nguyên vì cần debug", "Che/rút gọn trường nhạy cảm trước khi log, đặt retention phù hợp, giới hạn quyền đọc log bằng IAM", "Chuyển log sang S3 công khai"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Log cần đủ để quan sát nhưng tuân thủ bảo vệ dữ liệu cá nhân.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt log mất khả năng quan sát; giữ nguyên vi phạm bảo mật; S3 công khai làm lộ dữ liệu."},
  {"level": 3, "q": "Một dev đề xuất bật streaming cho job trích xuất ban đêm để \"giảm chi phí\". Nhận xét đúng?", "options": ["Đúng, streaming giảm 50%", "Streaming không đổi đơn giá token; nó cải thiện độ trễ cảm nhận và hữu ích cho output dài, còn giảm chi phí ban đêm nên dùng Batch", "Đúng, streaming bỏ qua max_tokens", "Streaming bắt buộc với Batch"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Phân biệt đòn bẩy UX/độ trễ với đòn bẩy giá.<br><strong>Vì sao các lựa chọn khác sai:</strong> Streaming không giảm giá; không bỏ qua max_tokens; Batch không dùng streaming."},
  {"level": 3, "q": "Pipeline hoá đơn dùng text tự do rồi parse, 8% request phải chạy lại do JSON sai. Thay đổi nào vừa giảm chi phí vừa tăng độ tin cậy?", "options": ["Thêm câu \"trả JSON hợp lệ nhé\" vào prompt", "Tăng temperature", "Chuyển sang structured output (json_schema) và validate bằng Zod trước khi lưu Prisma", "Parse bằng regex"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Output khớp schema giảm chạy lại, nên chi phí trên hoá đơn đúng giảm; Zod là lớp bảo vệ cuối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lời nhắc không đảm bảo; temperature không liên quan; regex giòn."},
  {"level": 3, "q": "Báo cáo doanh thu mỗi đêm: không cần realtime, cần người kế toán duyệt trước khi gửi ban giám đốc, ngân sách tháng cố định. Thiết kế tổng thể hợp lý?", "options": ["Realtime effort max, gửi thẳng ban giám đốc", "Model rẻ nhất, không duyệt để tiết kiệm thời gian", "Chạy thủ công khi nhớ ra", "Batch API + caching cho phần sinh báo cáo, effort chọn qua eval, lưu bản nháp vào DB chờ kế toán duyệt trên trang admin, dashboard chi phí trên mỗi báo cáo được duyệt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mỗi ràng buộc được đáp ứng: không realtime → Batch; duyệt → human-in-the-loop; ngân sách → đo chi phí mỗi kết quả được duyệt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Effort max realtime tốn kém và bỏ duyệt; model rẻ không eval và bỏ duyệt vi phạm yêu cầu; chạy thủ công không đáng tin."},
  {"level": 3, "q": "Đội đo agent chỉ bằng tỉ lệ thành công. Sau khi đổi prompt, tỉ lệ giữ 95% nhưng số lượt trung bình tăng từ 6 lên 14. Nên làm gì?", "options": ["Coi là hồi quy: chi phí và độ trễ tăng; xem log để tìm vòng lặp thừa và đưa số lượt/token vào tiêu chí eval", "Không sao vì tỉ lệ thành công giữ nguyên", "Tăng MAX_TURNS lên 30 để an toàn", "Giảm max_tokens để bù"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Eval cần theo dõi cả số lượt, token, thời gian; tỉ lệ thành công không phải chỉ số duy nhất.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ qua làm chi phí tăng gấp đôi; tăng trần che vấn đề; giảm max_tokens có thể gây cắt output."},
  {"level": 3, "q": "Agent hỗ trợ khách trên Bedrock (ap-southeast-1) cần giảm chi phí mà dữ liệu không rời AWS. Bước đầu tiên hợp lý?", "options": ["Chuyển sang API trực tiếp của Anthropic ngay để có giá khác", "Đo baseline chi phí trên mỗi ticket giải quyết, rồi áp dụng tối ưu miễn phí như prompt caching, cắt kết quả tool thừa, giảm vòng thừa, kiểm tra tính năng nào khả dụng trên Bedrock", "Đổi model rẻ nhất", "Tắt log để giảm chi phí CloudWatch"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Có baseline mới đo được cải thiện; tối ưu miễn phí đi trước; một số tính năng có thể khác trên Bedrock nên cần kiểm tra tài liệu.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chuyển nền tảng vi phạm ràng buộc dữ liệu; đổi model khi chưa eval là bẫy; tắt log mất khả năng quan sát."}
];
